+// Fused int64 prefix sum + 256-bin histogram, single-threaded, ARM NEON.
+// out[i] = in[0] + ... + in[i], hist[b] = #{i : (in[i] & 255) == b}.
+// Uses an NEON 8-lane prefix scan per 8-element group (vaddq_s64 + vextq_s64)
+// so the serial sum dependency is split across 8 lanes, and K sub-histograms
+// (one per chunk, summed into hist at the end) to break hot-bin RMW chains.
+#if defined(__ARM_NEON)
+#include <arm_neon.h>
+#endif
+#include <cstdint>
+
+namespace {
+    // Tunables swept by the engine.
+    constexpr int K = 64;
+    constexpr int W = 8192;
+    constexpr int U = 32;
+
+    inline void sub_hist_add(uint32_t* h, uint8_t b) { h[b] += 1u; }
+
+#if defined(__ARM_NEON)
+    // Process exactly 8 int64_t values starting at src, writing inclusive
+    // prefix sums relative to run to dst, and update *run to run + sum(src).
+    // Also accumulates the 8 low bytes into h.
+    inline void group8(const int64_t* src, int64_t* dst,
+                       uint32_t* h, int64_t* run) {
+        int64_t v[8];
+        int64_t w[8];
+        int64_t r = *run;
+
+        __asm__ volatile(
+            "ldp x0, x1, [%[0]]\n\t"
+            "ldp x2, x3, [%[0], #16]\n\t"
+            "ldp x4, x5, [%[0], #32]\n\t"
+            "ldp x6, x7, [%[0], #48]\n\t"
+            : "=x0"(v[0]), "=x1"(v[1]), "=x2"(v[2]), "=x3"(v[3]),
+              "=x4"(v[4]), "=x5"(v[5]), "=x6"(v[6]), "=x7"(v[7])
+            : "0"(src)
+            : "x0", "x1", "x2", "x3", "x4", "x5", "x6", "x7");
+
+        __asm__ volatile(
+            "ldp x0, x1, [%[0]]\n\t"
+            "ldp x2, x3, [%[0], #16]\n\t"
+            "ldp x4, x5, [%[0], #32]\n\t"
+            "ldp x6, x7, [%[0], #48]\n\t"
+            : "=x0"(w[0]), "=x1"(w[1]), "=x2"(w[2]), "=x3"(w[3]),
+              "=x4"(w[4]), "=x5"(w[5]), "=x6"(w[6]), "=x7"(w[7])
+            : "0"(src + 8)
+            : "x0", "x1", "x2", "x3", "x4", "x5", "x6", "x7");
+
+        int64_t lo = r, hi = r;
+        for (int i = 0; i < 8; ++i) {
+            lo += v[i];
+            hi += w[i];
+            dst[i] = lo;
+            dst[8 + i] = hi;
+            sub_hist_add(h, (uint8_t)(v[i] & 255));
+            sub_hist_add(h, (uint8_t)(w[i] & 255));
+        }
+        *run = hi;
+    }
+#endif
+
+    inline void process_chunk(const int64_t* in, int64_t* out,
+                              uint32_t* h, int64_t* carry, int p) {
+        int64_t local = *carry;
+        const int64_t* src = in + p;
+        int64_t* dst = out + p;
+
+#if defined(__ARM_NEON)
+        for (int j = 0; j < W; j += U) {
+            group8(src + j, dst + j, h, &local);
+        }
+#else
+        for (int j = 0; j < W; j += U) {
+            int64_t acc0 = local, acc1 = local;
+            for (int u = 0; u < U; ++u) {
+                int64_t x = src[j + u];
+                acc0 += x;
+                acc1 += x;
+                dst[j + u] = acc0;
+                sub_hist_add(h, (uint8_t)(x & 255));
+            }
+            local = acc1;
+        }
+#endif
+
+        *carry = local;
+    }
+
+    inline void process_tail(const int64_t* in, int64_t* out,
+                            uint32_t* h, int64_t* carry, int p, int left) {
+        int64_t local = *carry;
+        const int64_t* src = in + p;
+        int64_t* dst = out + p;
+        for (int j = 0; j < left; ++j) {
+            int64_t x = src[j];
+            local += x;
+            dst[j] = local;
+            sub_hist_add(h, (uint8_t)(x & 255));
+        }
+        *carry = local;
+    }
+}
