+
+    int64_t carry = 0;
+    size_t i = 0;
+    for (; i + (size_t)W <= n; i += (size_t)W) {
+        process_chunk(in, out, h[i / (size_t)W % K], &carry, (int)i);
     }
+    if (i < n) process_tail(in, out, h[i / (size_t)W % K], &carry, (int)i, (int)(n - i));
+
+    for (int k = 0; k < K; ++k)
